INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7271862, 1132043, 30982, '<td valign="top">This would be (in my opinion!) much better as either full color or full monochrome.  She''s such a beautiful young lady and has such a pensive, wistful, almost sad look - then there''s that banana standing out like a sore thumb tryng to draw attention away from her.  Does that make sense?  Really a great catch - I like the dreamy look, too.  Just not a fan of the selective desat.</td>', 'This would be (in my opinion!) much better as either full color or full monochrome.  She''s such a beautiful young lady and has such a pensive, wistful, almost sad look - then there''s that banana standing out like a sore thumb tryng to draw attention away from her.  Does that make sense?  Really a great catch - I like the dreamy look, too.  Just not a fan of the selective desat.', '2014-10-10 01:43:15.000000', NULL, 1),
(7271869, 1132109, 83313, '<td valign="top">Look! Up in the sky! It''s a bird! It''s a plane! It''s... a bird.</td>', 'Look! Up in the sky! It''s a bird! It''s a plane! It''s... a bird.', '2014-10-10 01:50:06.000000', NULL, 1),
(7271872, 1132132, 83313, '<td valign="top">What I find amazing is the goose is letting a person get so close. The ones near me will run off once I get to 15 feet or so.</td>', 'What I find amazing is the goose is letting a person get so close. The ones near me will run off once I get to 15 feet or so.', '2014-10-10 01:51:23.000000', NULL, 1),
(7271889, 1132110, 28742, '<td valign="top">This deserves ALL 10s. Unfortunately I can only give one of them.</td>', 'This deserves ALL 10s. Unfortunately I can only give one of them.', '2014-10-10 02:19:49.000000', NULL, 1),
(7271895, 1131897, 68504, '<td valign="top">at least 10. I am so moved.</td>', 'at least 10. I am so moved.', '2014-10-10 02:48:10.000000', NULL, 1),
