(7272102, 1132071, 170281, '<td valign="top">Very nice!  I have learn how to perform that colorizing.</td>', 'Very nice!  I have learn how to perform that colorizing.', '2014-10-10 16:41:25.000000', NULL, 1),
(7272104, 1132110, 170281, '<td valign="top">Love it!  There is nothing like the smile and laughter of a child.</td>', 'Love it!  There is nothing like the smile and laughter of a child.', '2014-10-10 17:03:08.000000', NULL, 1),
(7272155, 1131897, 111808, '<td valign="top">Absolutely stunning - the expressions of both people - acknowledgment, trust, concentration and Love just elevates this photo. I love the lead-in lines of the woman''s arm with the watch on it, time ticking away swiftly and the other lines of the man going the opposite way in his journey yet they still share a powerful connection. Superb and my favourite in this challenge.</td>', 'Absolutely stunning - the expressions of both people - acknowledgment, trust, concentration and Love just elevates this photo. I love the lead-in lines of the woman''s arm with the watch on it, time ticking away swiftly and the other lines of the man going the opposite way in his journey yet they still share a powerful connection. Superb and my favourite in this challenge.', '2014-10-10 21:49:51.000000', NULL, 1),
(7272191, 1131799, 117534, '<td valign="top">hummm shoulders are lean, can''t see adams apple, jaw is strong... I so want to say female, but the jaw, gonna say Male... Pretty colors and if she is a he, I am really po''d that he is prettier than me!!!!</td>', 'hummm shoulders are lean, can''t see adams apple, jaw is strong... I so want to say female, but the jaw, gonna say Male... Pretty colors and if she is a he, I am really po''d that he is prettier than me!!!!', '2014-10-11 00:24:17.000000', NULL, 1),
(7272192, 1132065, 117534, '<td valign="top">Those Oklahoma cowboys are the real thing!</td>', 'Those Oklahoma cowboys are the real thing!', '2014-10-11 00:26:02.000000', NULL, 1),
(7272193, 1132132, 117534, '<td valign="top">hummm swan butt...</td>', 'hummm swan butt...', '2014-10-11 00:28:09.000000', NULL, 1),
