(7272313, 1132078, 124982, '<td valign="top">An extraordinary capture! Such an intriguing image filled with glorious contrasts!</td>', 'An extraordinary capture! Such an intriguing image filled with glorious contrasts!', '2014-10-11 18:23:02.000000', NULL, 1),
(7272315, 1132071, 124982, '<td valign="top">Really liked the image and composition, but not a fan of the selective desaturation which, to me, does not suit the image or contribute anything meaningful.</td>', 'Really liked the image and composition, but not a fan of the selective desaturation which, to me, does not suit the image or contribute anything meaningful.', '2014-10-11 18:24:52.000000', NULL, 1),
(7272317, 1132143, 124982, '<td valign="top">Such strong character .. great capture!</td>', 'Such strong character .. great capture!', '2014-10-11 18:25:31.000000', NULL, 1),
(7272318, 1131585, 124982, '<td valign="top">Top 5 for me. Great candid image and curious composition!</td>', 'Top 5 for me. Great candid image and curious composition!', '2014-10-11 18:26:55.000000', NULL, 1),
(7272320, 1131897, 124982, '<td valign="top">A delicate commentary on the fleeting nature of life. Very strong image!! Top 5!</td>', 'A delicate commentary on the fleeting nature of life. Very strong image!! Top 5!', '2014-10-11 18:27:33.000000', NULL, 1),
(7272324, 1132065, 20679, '<td valign="top">Wonderful capture!</td>', 'Wonderful capture!', '2014-10-11 18:55:45.000000', NULL, 1),
