(7272329, 1132137, 20679, '<td valign="top">Doesn''t matter to me that she is out of focus. Love this.</td>', 'Doesn''t matter to me that she is out of focus. Love this.', '2014-10-11 18:57:38.000000', NULL, 1),
(7272330, 1131988, 20679, '<td valign="top">HAHA! I can relate to this. Great candid image!</td>', 'HAHA! I can relate to this. Great candid image!', '2014-10-11 18:58:06.000000', NULL, 1),
(7272332, 1131829, 20679, '<td valign="top">Sepia works well here for me. I like it a lot</td>', 'Sepia works well here for me. I like it a lot', '2014-10-11 18:58:32.000000', NULL, 1),
(7272333, 1132127, 20679, '<td valign="top">Great capture - a true candid moment that leaves us wondering....</td>', 'Great capture - a true candid moment that leaves us wondering....', '2014-10-11 18:59:07.000000', NULL, 1),
(7272335, 1132132, 20679, '<td valign="top">Yep, this is what we do! Great!</td>', 'Yep, this is what we do! Great!', '2014-10-11 18:59:33.000000', NULL, 1),
