(7272354, 1131585, 121111, '<td valign="top">bored? watching? listening to someone whine ?<br/>10</td>', 'bored? watching? listening to someone whine ?10', '2014-10-11 19:49:24.000000', NULL, 1),
(7272504, 1132110, 69324, '<td valign="top">Makes me smile.</td>', 'Makes me smile.', '2014-10-11 22:40:12.000000', NULL, 1),
(7272506, 1132142, 69324, '<td valign="top">This is funny.</td>', 'This is funny.', '2014-10-11 22:41:14.000000', NULL, 1),
(7272523, 1132106, 96751, '<td valign="top">An interesting shot for sure, but it is the pp''g which I''m looking at more than the content</td>', 'An interesting shot for sure, but it is the pp''g which I''m looking at more than the content', '2014-10-11 23:17:09.000000', NULL, 1),
(7272524, 1131896, 96751, '<td valign="top">I know this place :)<br/> <br/>Lovely treatment. Like an echo of the real thing.</td>', 'I know this place :) Lovely treatment. Like an echo of the real thing.', '2014-10-11 23:18:31.000000', NULL, 1),
(7272525, 1132065, 96751, '<td valign="top">Beautiful light.</td>', 'Beautiful light.', '2014-10-11 23:19:09.000000', NULL, 1),
(7272526, 1132143, 96751, '<td valign="top">The brilliance of this is not only her expression but how the focus falls off sharply behind her. My only nit is the bokeh on the left near her shoulders. Those highlights could have been toned down to keep from drawing the eye there.</td>', 'The brilliance of this is not only her expression but how the focus falls off sharply behind her. My only nit is the bokeh on the left near her shoulders. Those highlights could have been toned down to keep from drawing the eye there.', '2014-10-11 23:21:21.000000', NULL, 1),
(7272527, 1132069, 96751, '<td valign="top">This is a blurry mess, and yet...</td>', 'This is a blurry mess, and yet...', '2014-10-11 23:22:42.000000', NULL, 1),
(7272528, 1132056, 96751, '<td valign="top">Sweet portrait, but I feel the pp''g has truly dulled the moment.</td>', 'Sweet portrait, but I feel the pp''g has truly dulled the moment.', '2014-10-11 23:24:37.000000', NULL, 1),
(7272529, 1132132, 96751, '<td valign="top">Yeah, that would be me. LOVE it.</td>', 'Yeah, that would be me. LOVE it.', '2014-10-11 23:25:52.000000', NULL, 1),
(7272530, 1132110, 96751, '<td valign="top">Marvelous joy. The unseen kite is as much a part of this as the child''s laugh.</td>', 'Marvelous joy. The unseen kite is as much a part of this as the child''s laugh.', '2014-10-11 23:27:18.000000', NULL, 1),
(7272531, 1132135, 96751, '<td valign="top">Nice framing.  Although it makes me feel like a voyeur :)</td>', 'Nice framing.  Although it makes me feel like a voyeur :)', '2014-10-11 23:28:20.000000', NULL, 1),
(7272534, 1132051, 24073, '<td valign="top">Dont think it gets better than this, great image, composed awesome, and I love the crisp, clean, clear image.  The water in the back goes right up to the edge of the levels, and then the darks under the bridge, so well balanced, and great shades of grey for the shot.  I love it.</td>', 'Dont think it gets better than this, great image, composed awesome, and I love the crisp, clean, clear image.  The water in the back goes right up to the edge of the levels, and then the darks under the bridge, so well balanced, and great shades of grey for the shot.  I love it.', '2014-10-11 23:43:35.000000', NULL, 1),
(7272536, 1131698, 24073, '<td valign="top">Beautiful, I''m sure I don''t have to tell you that.  The amber is just mind blowingly gorgeous, the sky, the clouds the sun rays in the clouds.  You have executed an awesome shot. great job.</td>', 'Beautiful, I''m sure I don''t have to tell you that.  The amber is just mind blowingly gorgeous, the sky, the clouds the sun rays in the clouds.  You have executed an awesome shot. great job.', '2014-10-11 23:45:23.000000', NULL, 1),
(7272682, 1132143, 113156, '<td valign="top">Nicely captured candid, compositionally i feel it''s slightly awkward though.</td>', 'Nicely captured candid, compositionally i feel it''s slightly awkward though.', '2014-10-12 11:20:29.000000', NULL, 1),
(7272694, 1131585, 113156, '<td valign="top">Excellent ambiance.</td>', 'Excellent ambiance.', '2014-10-12 11:24:53.000000', NULL, 1),
(7272703, 1132113, 113156, '<td valign="top">I''m loving this, fluid and harmoniouse.</td>', 'I''m loving this, fluid and harmoniouse.', '2014-10-12 11:28:49.000000', NULL, 1),
(7272709, 1132137, 113156, '<td valign="top">You got the mooves, lovely candid.</td>', 'You got the mooves, lovely candid.', '2014-10-12 11:30:43.000000', NULL, 1),
(7272730, 1131988, 118154, '<td valign="top">One of my favs this challenge.8.</td>', 'One of my favs this challenge.8.', '2014-10-12 12:10:32.000000', NULL, 1),
(7272732, 1132131, 118154, '<td valign="top">Finding it hard to think of this as a candid.</td>', 'Finding it hard to think of this as a candid.', '2014-10-12 12:12:50.000000', NULL, 1),
(7272733, 1132137, 118154, '<td valign="top">8</td>', '8', '2014-10-12 12:13:05.000000', NULL, 1),
(7272734, 1131799, 118154, '<td valign="top">Don,t have to.</td>', 'Don,t have to.', '2014-10-12 12:14:12.000000', NULL, 1),
(7272824, 1132060, 13077, '<td valign="top">Cute dog, but the noise and softness from the low light conditions don''t make the photo very pleasing to look at.</td>', 'Cute dog, but the noise and softness from the low light conditions don''t make the photo very pleasing to look at.', '2014-10-12 17:00:41.000000', NULL, 1),
(7272826, 1132131, 13077, '<td valign="top">He''s got that sleep-til-sunday-night-rollover feeling</td>', 'He''s got that sleep-til-sunday-night-rollover feeling', '2014-10-12 17:01:41.000000', NULL, 1),
(7272828, 1132052, 13077, '<td valign="top">Well he looks thrilled! lol<br/>Well captured moment and good composition.</td>', 'Well he looks thrilled! lolWell captured moment and good composition.', '2014-10-12 17:02:17.000000', NULL, 1),
(7272829, 1132080, 13077, '<td valign="top">Very cute moment and well captured, good composition and tones.</td>', 'Very cute moment and well captured, good composition and tones.', '2014-10-12 17:02:37.000000', NULL, 1),
(7272831, 1132137, 13077, '<td valign="top">I really like how the girl in the foreground seems to be trying to figure out if you''re taking her picture or not. I also like how she''s out of focus but everything else is in. It works well. Excellent composition and light.</td>', 'I really like how the girl in the foreground seems to be trying to figure out if you''re taking her picture or not. I also like how she''s out of focus but everything else is in. It works well. Excellent composition and light.', '2014-10-12 17:03:52.000000', NULL, 1),
(7272833, 1132122, 13077, '<td valign="top">Clever title.</td>', 'Clever title.', '2014-10-12 17:04:13.000000', NULL, 1),
(7272836, 1132097, 13077, '<td valign="top">Nicely captured and composed. I like how they''re shooting in opposite directions, wearing opposite colors, and in front of opposite colored parts of the scene.</td>', 'Nicely captured and composed. I like how they''re shooting in opposite directions, wearing opposite colors, and in front of opposite colored parts of the scene.', '2014-10-12 17:06:18.000000', NULL, 1),
(7272837, 1131934, 13077, '<td valign="top">As good a place as any. Well composed with the rest of the people in the scene, and the tones look great.</td>', 'As good a place as any. Well composed with the rest of the people in the scene, and the tones look great.', '2014-10-12 17:06:54.000000', NULL, 1),
(7272838, 1131882, 13077, '<td valign="top">Nicely captured moment, and I like how the people in the background are still in focus enough to see that they are all doing their own thing.</td>', 'Nicely captured moment, and I like how the people in the background are still in focus enough to see that they are all doing their own thing.', '2014-10-12 17:07:26.000000', NULL, 1),
(7272841, 1132065, 13077, '<td valign="top">Oklahoma, hmm, my current neck of the woods.<br/>Very good moment and good light and processing.</td>', 'Oklahoma, hmm, my current neck of the woods.Very good moment and good light and processing.', '2014-10-12 17:08:27.000000', NULL, 1),
(7272843, 1132128, 13077, '<td valign="top">I feel for her, getting caught literally in the middle of a conversation she doesn''t want to be part of.<br/>The diagonal composition actually works well here, mainly because of the two ladies in the background.<br/>I like it.</td>', 'I feel for her, getting caught literally in the middle of a conversation she doesn''t want to be part of.The diagonal composition actually works well here, mainly because of the two ladies in the background.I like it.', '2014-10-12 17:09:25.000000', NULL, 1),
(7272854, 1132109, 13077, '<td valign="top">I like it. Good moment and simple composition, well exposed as well.</td>', 'I like it. Good moment and simple composition, well exposed as well.', '2014-10-12 17:16:38.000000', NULL, 1),
(7272856, 1132090, 13077, '<td valign="top">I very much like that the girl is hiding her face but the lady''s face is on the posters plastered all over that storefront.<br/>I also like the shadow of the guy in the glass to the right.<br/>Fascinating.</td>', 'I very much like that the girl is hiding her face but the lady''s face is on the posters plastered all over that storefront.I also like the shadow of the guy in the glass to the right.Fascinating.', '2014-10-12 17:18:27.000000', NULL, 1),
(7273073, 1131732, 63218, '<td valign="top">Wow! Well done!</td>', 'Wow! Well done!', '2014-10-13 09:50:38.000000', NULL, 1),
(7273243, 1132126, 13077, '<td valign="top">Nicely captured with the fly and all of the line in the air. It might have been even more visually impressive in front of a cleaner background, but still.</td>', 'Nicely captured with the fly and all of the line in the air. It might have been even more visually impressive in front of a cleaner background, but still.', '2014-10-13 18:12:44.000000', NULL, 1),
(7273245, 1132058, 13077, '<td valign="top">I think the composition would have worked better with the man and kid positioned completely in front of the white section of wall. There also seems to be a bit of motion blur.</td>', 'I think the composition would have worked better with the man and kid positioned completely in front of the white section of wall. There also seems to be a bit of motion blur.', '2014-10-13 18:13:37.000000', NULL, 1),
(7273246, 1132100, 13077, '<td valign="top">Nice. Graphic, up close and personal, a great moment and a storytelling photo. Good newspaper stuff.<br/>Nitpicking - A little more depth of field couldn''t have hurt, to include the boy''s face in sharper focus.</td>', 'Nice. Graphic, up close and personal, a great moment and a storytelling photo. Good newspaper stuff.Nitpicking - A little more depth of field couldn''t have hurt, to include the boy''s face in sharper focus.', '2014-10-13 18:14:57.000000', NULL, 1),
(7273248, 1131988, 13077, '<td valign="top">Excellent moment, good composition and tones. Was there a bigger dog on the other side of the intersection? Also perfect shutter speed, I  like the slight motion visible in the dog''s leg and tail while everything else is sharp.</td>', 'Excellent moment, good composition and tones. Was there a bigger dog on the other side of the intersection? Also perfect shutter speed, I  like the slight motion visible in the dog''s leg and tail while everything else is sharp.', '2014-10-13 18:18:05.000000', NULL, 1),
(7273249, 1131996, 13077, '<td valign="top">Well captured and composed with the shapes in the foreground adding some drama rather than just a distraction. Very good light as well, and good job not blowing out the window in the background.</td>', 'Well captured and composed with the shapes in the foreground adding some drama rather than just a distraction. Very good light as well, and good job not blowing out the window in the background.', '2014-10-13 18:19:02.000000', NULL, 1),
(7273250, 1132084, 13077, '<td valign="top">Well captured, excellent light and composition and just enough depth of field to include the background for reference and interest but not make it too busy.</td>', 'Well captured, excellent light and composition and just enough depth of field to include the background for reference and interest but not make it too busy.', '2014-10-13 18:20:17.000000', NULL, 1),
(7273252, 1132141, 13077, '<td valign="top">Bold use of mostly-white tones here. Almost a surreal take on the scene but gritty at the same time with the grain in the midtones and shadows.</td>', 'Bold use of mostly-white tones here. Almost a surreal take on the scene but gritty at the same time with the grain in the midtones and shadows.', '2014-10-13 18:21:18.000000', NULL, 1),
(7273253, 1132101, 13077, '<td valign="top">I don''t find this interesting or appealing.</td>', 'I don''t find this interesting or appealing.', '2014-10-13 18:24:44.000000', NULL, 1),
(7273254, 1131897, 13077, '<td valign="top">A very poignant, tender moment, made stronger by your title. Absolutely top-notch photojournalistic image, assuming the story behind it is being accurately told here.<br/> <br/>Perfect light and excellent composition and processing. I like the sharpness in their character-filled faces and the lines in her hands.</td>', 'A very poignant, tender moment, made stronger by your title. Absolutely top-notch photojournalistic image, assuming the story behind it is being accurately told here. Perfect light and excellent composition and processing. I like the sharpness in their character-filled faces and the lines in her hands.', '2014-10-13 18:29:05.000000', NULL, 1),
(7273255, 1132113, 13077, '<td valign="top">I like it a lot. Excellent study of shapes and shadows, impeccably timed and composed. The toning comes across as sort of purple on my screen, but I the impression I get from that is it''s the way Provia slide film looks under certain lighting conditions and exposure levels.</td>', 'I like it a lot. Excellent study of shapes and shadows, impeccably timed and composed. The toning comes across as sort of purple on my screen, but I the impression I get from that is it''s the way Provia slide film looks under certain lighting conditions and exposure levels.', '2014-10-13 18:31:37.000000', NULL, 1),
(7273256, 1132145, 13077, '<td valign="top">Well composed and perfect shutter speed to capture the moving propeller in such a cool looking manner, but I''m not a fan of the added border.</td>', 'Well composed and perfect shutter speed to capture the moving propeller in such a cool looking manner, but I''m not a fan of the added border.', '2014-10-13 18:32:54.000000', NULL, 1),
(7273257, 1131782, 13077, '<td valign="top">I think this would have been stronger without the motion blur, and I''m not a fan of the processing style.</td>', 'I think this would have been stronger without the motion blur, and I''m not a fan of the processing style.', '2014-10-13 18:33:20.000000', NULL, 1),
(7273258, 1131816, 13077, '<td valign="top">I think a longer lens would have made the most of this scene - including the man on the left''s whole body is a good move, including the regular dressed people and the pop-up canopies is a bad move.<br/> <br/>A tighter composition with shallower depth of field would have made the most out of their traditional dress and ceremonial gear, without the junk.</td>', 'I think a longer lens would have made the most of this scene - including the man on the left''s whole body is a good move, including the regular dressed people and the pop-up canopies is a bad move. A tighter composition with shallower depth of field would have made the most out of their traditional dress and ceremonial gear, without the junk.', '2014-10-13 18:35:03.000000', NULL, 1),
(7273259, 1131737, 13077, '<td valign="top">A good moment, well exposed and good tones but the composition could have been improved. Having the man in the background growing out of the sleeping lady''s hip makes him a distraction, which is also what the object in the foreground to the right is.</td>', 'A good moment, well exposed and good tones but the composition could have been improved. Having the man in the background growing out of the sleeping lady''s hip makes him a distraction, which is also what the object in the foreground to the right is.', '2014-10-13 18:36:03.000000', NULL, 1),
(7273260, 1131585, 13077, '<td valign="top">I love the way his eyes and face position almost match the face emerging from the abstract shapes in the painting. Excellent job capturing this, with perfect exposure and light, and the slight bit of softness and grain just makes it raw and gritty and real.</td>', 'I love the way his eyes and face position almost match the face emerging from the abstract shapes in the painting. Excellent job capturing this, with perfect exposure and light, and the slight bit of softness and grain just makes it raw and gritty and real.', '2014-10-13 18:37:30.000000', NULL, 1),
(7273261, 1132056, 13077, '<td valign="top">It has potential, but I''m not a fan of the processing, and the composition might have been improved by walking to the right a bit to have the dog by the lady''s side as a companion, rather than in front of her and taking up more of the frame than she does.</td>', 'It has potential, but I''m not a fan of the processing, and the composition might have been improved by walking to the right a bit to have the dog by the lady''s side as a companion, rather than in front of her and taking up more of the frame than she does.', '2014-10-13 18:38:42.000000', NULL, 1),
(7273262, 1132132, 13077, '<td valign="top">LOL!<br/>What a nicely captured moment, I wonder what the goose was thinking. "Yeah, I''ve been hitting the gym working on those glutes, let me flex ''em for ya"</td>', 'LOL!What a nicely captured moment, I wonder what the goose was thinking. "Yeah, I''ve been hitting the gym working on those glutes, let me flex ''em for ya"', '2014-10-13 18:39:33.000000', NULL, 1),
(7273264, 1132135, 13077, '<td valign="top">I don''t get the title, and I''m not crazy about the visual aspects of the photo either. Interesting framing with the hedge, but it just ends up too busy in this case and there seems to be some motion blur as well.</td>', 'I don''t get the title, and I''m not crazy about the visual aspects of the photo either. Interesting framing with the hedge, but it just ends up too busy in this case and there seems to be some motion blur as well.', '2014-10-13 18:41:33.000000', NULL, 1),
(7273265, 1132071, 13077, '<td valign="top">I think recomposing to have him more in front of the simple cabinet in the back and using a smaller aperture to bring more of the scene into focus would have helped. Also, while I like the selective coloring bringing only the green parts of the photo into color, there are some green parts in the background and I would have preferred to have them desaturated as well, with only the tree he''s pruning and the leaves on the table being in color.</td>', 'I think recomposing to have him more in front of the simple cabinet in the back and using a smaller aperture to bring more of the scene into focus would have helped. Also, while I like the selective coloring bringing only the green parts of the photo into color, there are some green parts in the background and I would have preferred to have them desaturated as well, with only the tree he''s pruning and the leaves on the table being in color.', '2014-10-13 18:43:18.000000', NULL, 1),
(7273266, 1132051, 13077, '<td valign="top">A nicely captured and composed moment, and as a father I''m glad to see he''s got a good hold on his son''s hand.</td>', 'A nicely captured and composed moment, and as a father I''m glad to see he''s got a good hold on his son''s hand.', '2014-10-13 18:44:15.000000', NULL, 1),
(7273267, 1132048, 13077, '<td valign="top">I like the cheerful feel of this.</td>', 'I like the cheerful feel of this.', '2014-10-13 18:45:31.000000', NULL, 1),
(7273268, 1132110, 13077, '<td valign="top">That looks like so much fun! I like the joy you''ve captured here. If I were to nitpick, I might like a little less of the grass in the foreground and a little more of the kite string.</td>', 'That looks like so much fun! I like the joy you''ve captured here. If I were to nitpick, I might like a little less of the grass in the foreground and a little more of the kite string.', '2014-10-13 18:46:11.000000', NULL, 1),
(7273269, 1131723, 13077, '<td valign="top">LOL, it really does look like she''s about to get hit with that post.</td>', 'LOL, it really does look like she''s about to get hit with that post.', '2014-10-13 18:46:35.000000', NULL, 1),
(7273271, 1132139, 13077, '<td valign="top">Cute subject and a good moment, and I like the composition. Not sure about the selective coloring, or maybe that''s just the toning but the sky has more saturation in it and I don''t think that adds anything to the photo.</td>', 'Cute subject and a good moment, and I like the composition. Not sure about the selective coloring, or maybe that''s just the toning but the sky has more saturation in it and I don''t think that adds anything to the photo.', '2014-10-13 18:47:40.000000', NULL, 1),
(7273272, 1132088, 13077, '<td valign="top">Excellent street scene. I love all the elements and the ''characters'' in it, how they are all doing their own thing and the whole thing just tells a story but I''m not sure what it is yet. Very interesting.</td>', 'Excellent street scene. I love all the elements and the ''characters'' in it, how they are all doing their own thing and the whole thing just tells a story but I''m not sure what it is yet. Very interesting.', '2014-10-13 18:51:00.000000', NULL, 1),
(7273273, 1132098, 13077, '<td valign="top">Excellent. I like the people, the light, the composition, and the soft colors. The sleeping man clutching his hat and the daydreaming lady are just fascinating.</td>', 'Excellent. I like the people, the light, the composition, and the soft colors. The sleeping man clutching his hat and the daydreaming lady are just fascinating.', '2014-10-13 18:53:05.000000', NULL, 1),
(7273274, 1131799, 13077, '<td valign="top">Good job on the processing here, the colors look very natural. The background is a bit busy and a tighter composition might have been had, but as a slice-of-life shot it''s interesting to see the other goings-on in the background and foreground, especially the guy with the beer bottle.</td>', 'Good job on the processing here, the colors look very natural. The background is a bit busy and a tighter composition might have been had, but as a slice-of-life shot it''s interesting to see the other goings-on in the background and foreground, especially the guy with the beer bottle.', '2014-10-13 18:55:38.000000', NULL, 1),
(7273275, 1132146, 13077, '<td valign="top">Always fun. These were challenging lighting conditions and you haven''t completely blown out the sunny areas, but they''re close. Maybe if a wider aperture was to be had? Failing that, not sure how much you could have manipulated the scene but moving the bucket into a place where the background was cleaner and less bright, and getting the little boy to keep playing it might have resulted in something excellent.</td>', 'Always fun. These were challenging lighting conditions and you haven''t completely blown out the sunny areas, but they''re close. Maybe if a wider aperture was to be had? Failing that, not sure how much you could have manipulated the scene but moving the bucket into a place where the background was cleaner and less bright, and getting the little boy to keep playing it might have resulted in something excellent.', '2014-10-13 18:57:28.000000', NULL, 1),
(7273277, 1132143, 13077, '<td valign="top">She''s thinking "I don''t have time for this s***..."</td>', 'She''s thinking "I don''t have time for this s***..."', '2014-10-13 18:58:15.000000', NULL, 1),
(7273279, 1131999, 13077, '<td valign="top">I get the impression he was standing there listening to all their conversations for a while before he got to pay up and take his food.</td>', 'I get the impression he was standing there listening to all their conversations for a while before he got to pay up and take his food.', '2014-10-13 18:58:56.000000', NULL, 1),
(7273280, 1132085, 13077, '<td valign="top">I deleted it for him! bwahahaha</td>', 'I deleted it for him! bwahahaha', '2014-10-13 18:59:23.000000', NULL, 1),
(7273281, 1132043, 13077, '<td valign="top">I get the impression someone is trying to take her banana away and she''s using the puppy dog eyes to convince him otherwise.</td>', 'I get the impression someone is trying to take her banana away and she''s using the puppy dog eyes to convince him otherwise.', '2014-10-13 19:05:32.000000', NULL, 1),
