(7273285, 1132106, 13077, '<td valign="top">Well composed and I like the detail in the blood and guts and rust, while the processing makes it feel almost like a cartoon.</td>', 'Well composed and I like the detail in the blood and guts and rust, while the processing makes it feel almost like a cartoon.', '2014-10-13 19:09:02.000000', NULL, 1),
(7273286, 1131670, 13077, '<td valign="top">A nice moment with very good light and well exposed and timed, but I don''t feel like the man on the left being partially inlcuded is adding anything; I would have cropped him out.</td>', 'A nice moment with very good light and well exposed and timed, but I don''t feel like the man on the left being partially inlcuded is adding anything; I would have cropped him out.', '2014-10-13 19:10:17.000000', NULL, 1),
